# Mock "abnormal vitals" evaluation function for test
def abnormal_vitals(records):
    for record in records:
        vitals = record.get('vitals', {})
        # Example abnormal rule: heart_rate < 50 or > 120; bp systolic < 95 or > 140
        hr = vitals.get('heart_rate')
        if hr is not None and (hr < 50 or hr > 120):
            return True
        bp = vitals.get('bp_sys')
        if bp is not None and (bp < 95 or bp > 140):
            return True
    return False

