        self.age = age  # patient's age: int
        self.conditions = conditions  # list of condition strings
        self.severities = severities  # list of float severity values

    def get_total_conditions(self):
        return len(self.conditions)

    def get_average_severity(self):
        if not self.severities:
            return 0.0
        return sum(self.severities) / len(self.severities)

class Hospital:
    def __init__(self, patients, records):
        self.patients = patients  # dict patient_id: Patient
        self.records = records    # dict patient_id: list of dicts

    def get_patient(self, patient_id):
        return self.patients[patient_id]

