    score_int_fields = {'technical_score', 'communication_score', 'teamwork_score', 'leadership_score'}
    float_fields = {'overall_rating'}
    # Everything else remains string

    data = []
    with open(file_path, encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for r in reader:
            record = {}
            for k, v in r.items():
                if k in score_int_fields:
                    record[k] = int(v)
                elif k in float_fields:
                    record[k] = float(v)
                else:
                    record[k] = v
            data.append(record)

    if report_type == 'department' and employee_id is None:
        from collections import defaultdict
        departments = defaultdict(list)
        # Group rows by department
        for row in data:
            departments[row['department']].append(row)
        result = {}
        for dept, items in departments.items():
            ratings = [row['overall_rating'] for row in items]
            avg_rating = sum(ratings) / len(ratings) if ratings else 0.0
            result[dept] = {'avg_rating': avg_rating, 'count': len(items)}
        return result

    # Otherwise, find row by employee_id
    found = None
    for row in data:
        if row['employee_id'] == employee_id:
            found = row
            break
    if found is None:
        return None

    if report_type == 'summary':
        return {'employee_id': found['employee_id'],
                'overall_rating': found['overall_rating'],
                'goals_status': found['goals_status']}
    elif report_type == 'detailed':
        return found
    else:
        raise ValueError(f"Unknown report_type {report_type}")

